/* channel.suspicious_user.message v1 */

export const ChannelSuspiciousUserMessageCondition = Schema.Struct({
  moderator_user_id: Schema.String,
  broadcaster_user_id: Schema.String,
});

/**
 * The 'channel.suspicious_user.message' subscription type sends a notification when a suspicious
 * user sends a chat message in the broadcaster's channel. Only users whose status is
 * active_monitoring or restricted trigger the notification. The notification is sent even when the
 * message doesn't appear in chat: a restricted user's messages are withheld from chat, and AutoMod
 * may hold the message for review. In a shared chat session, the notification is sent only for the
 * channel where the user sent the message. If AutoMod holds the message and a moderator allows it,
 * you may receive a second notification for the allowed message, with a different 'message_id'.
 */
export const ChannelSuspiciousUserMessagePayload = Schema.Struct({
  broadcaster_user_id: Schema.String,
  broadcaster_user_name: Schema.String,
  broadcaster_user_login: Schema.String,
  user_id: Schema.String,
  user_name: Schema.String,
  user_login: Schema.String,
  low_trust_status: OpenLiterals(["active_monitoring", "restricted"]),
  shared_ban_channel_ids: Schema.optional(Schema.NullOr(Schema.Array(Schema.String))),
  types: Schema.Array(OpenLiterals(["manually_added", "ban_evader", "banned_in_shared_channel"])),
  ban_evasion_evaluation: OpenLiterals(["possible", "likely", "unknown"]),
  message: Schema.Struct({
    message_id: Schema.String,
    text: Schema.String,
    fragments: Schema.Array(Schema.Struct({
      type: OpenLiterals(["text", "cheermote", "emote"]),
      text: Schema.String,
      cheermote: Schema.optional(Schema.NullOr(Schema.Struct({
        prefix: Schema.String,
        bits: Schema.Int,
        tier: Schema.Int,
      }))),
      emote: Schema.optional(Schema.NullOr(Schema.Struct({
        id: Schema.String,
        emote_set_id: Schema.String,
      }))),
    })),
  }),
});

