/* user.authorization.grant v1 */

export const UserAuthorizationGrantCondition = Schema.Struct({
  client_id: Schema.String,
});

/**
 * The 'user.authorization.grant' subscription type sends a notification each time a user authorizes
 * your client id. That's the first time they authorize your app, and again each time they authorize
 * it afterwards through the authorization code, implicit grant, or device code flow. This includes
 * when they grant additional scopes, and when Twitch approves the request without prompting them
 * because they already granted the requested scopes (*force_verify* isn't true). Twitch sends the
 * notification when the request is approved, whether or not your app then exchanges the code or
 * gets a token. A repeat authorization has the same payload as the first one.
 */
export const UserAuthorizationGrantPayload = Schema.Struct({
  client_id: Schema.String,
  user_id: Schema.String,
  user_login: Schema.String,
  user_name: Schema.String,
});

/* user.authorization.revoke v1 */

export const UserAuthorizationRevokeCondition = Schema.Struct({
  client_id: Schema.String,
});

/**
 * The 'user.authorization.revoke' subscription type sends a notification when a user's
 * authorization for your client ID is revoked. This happens when the user disconnects your app, and
 * also when Twitch revokes the user's authorizations: for example, when the user changes or resets
 * their password, turns on two-factor authentication, or signs out of all sessions, and when the
 * user's account is deleted, disabled, or suspended. The notification doesn't say why the
 * authorization was revoked. Revoking an access token or refresh token doesn't send this
 * notification. Use this subscription to meet government requirements for handling user data, such
 * as GDPR, LGPD, or CCPA.
 */
export const UserAuthorizationRevokePayload = Schema.Struct({
  client_id: Schema.String,
  user_id: Schema.String,
  user_login: Schema.optional(Schema.NullOr(Schema.String)),
  user_name: Schema.optional(Schema.NullOr(Schema.String)),
});

